<?php
namespace App\Http\Controllers;
use App\Models\AttendanceCorrection; use App\Models\AttendanceRecord; use App\Models\Employee; use App\Services\WorkforceAuditService; use Carbon\Carbon; use Illuminate\Http\Request;
class AttendanceController extends Controller {
 public function index(){ $records=AttendanceRecord::query()->with(['employee','rosterAssignment','corrections'=>fn($q)=>$q->where('status','pending')])->latest('work_date')->paginate(30); $corrections=AttendanceCorrection::with(['employee','attendanceRecord'])->where('status','pending')->latest()->limit(30)->get(); return view('workforce.attendance.index',compact('records','corrections')); }
 public function store(Request $r, WorkforceAuditService $audit){ $data=$r->validate(['employee_id'=>'required|exists:employees,id','work_date'=>'required|date','clock_in_at'=>'nullable|date','clock_out_at'=>'nullable|date|after:clock_in_at','status'=>'required|in:present,late,absent,on_leave,off_duty','unit_id'=>'nullable|exists:units,id','roster_assignment_id'=>'nullable|exists:roster_assignments,id','exception_reason'=>'nullable|string|max:1000']); $data['recorded_by']=auth()->id(); if($data['clock_in_at']??false && $data['clock_out_at']??false){$data['worked_minutes']=(int)round((strtotime($data['clock_out_at'])-strtotime($data['clock_in_at']))/60);} if(!empty($data['roster_assignment_id'])){$a=\App\Models\RosterAssignment::find($data['roster_assignment_id']); if($a && !empty($data['clock_in_at'])){$planned=Carbon::parse($data['work_date'].' '.$a->start_time);$actual=Carbon::parse($data['clock_in_at']);$data['late_minutes']=max(0,$planned->diffInMinutes($actual,false));} if($a && !empty($data['clock_out_at'])){$plannedOut=Carbon::parse($data['work_date'].' '.$a->end_time); if($a->end_time <= $a->start_time)$plannedOut->addDay(); $actualOut=Carbon::parse($data['clock_out_at']);$data['early_departure_minutes']=max(0,$actualOut->diffInMinutes($plannedOut,false));}} $rec=AttendanceRecord::updateOrCreate(['employee_id'=>$data['employee_id'],'work_date'=>$data['work_date']],$data); $audit->model('updated',$rec,'Attendance recorded/updated'); return back()->with('success','Attendance saved.'); }
}
